const targets = Array.from(game.user.targets);
if (!targets.length) return ui.notifications.warn("Please target at least one token!");

// V13 Modern Input Dialog
const data = await foundry.applications.api.DialogV2.input({
  window: { title: "Edit_HP" },
  content: `
    <div class="form-group">
      <label>Edit_HP</label>
      <div class="form-fields">
        <!-- Changed type to "text" to allow lazy math strings -->
        <input type="text" name="hpAdjustment" placeholder="0" autofocus>
      </div>
    </div>`,
  ok: { label: "Apply", icon: "fa-solid fa-burst" }
});

// Check if user cancelled or input is empty
if (!data || !data.hpAdjustment) return;

// --- LAZY INPUT LOGIC ---
// Find all numbers including their leading + or -
const matches = data.hpAdjustment.match(/[+-]?\d+/g);
if (!matches) return ui.notifications.error("No valid numbers found in input.");

// Sum them up
const totalAdjustment = matches.reduce((acc, num) => acc + parseInt(num), 0);
// ------------------------

for (let token of targets) {
  const actor = token.actor;
  const hpPath = "system.health.value";
  const hpMax = "system.health.max";
  const currentHP = foundry.utils.getProperty(actor, hpPath);
  const maxHP = foundry.utils.getProperty(actor, hpMax);

  if (currentHP === undefined || maxHP === undefined) {
    console.warn(`Plume | ${token.name} does not have health defined.`);
    continue;
  }

  // Calculate new HP (Clamped between -999 and Max)
  const newHP = Math.clamp(currentHP + totalAdjustment, -999, maxHP);
  await actor.update({ [hpPath]: newHP });

  // Simple Chat Feedback
  await ChatMessage.create({
    speaker: ChatMessage.getSpeaker({ token: token.document }),
    content: `
      <div class="dice-roll">
        <div class="dice-result">
          <div class="dice-total" style="color: #000000; border: 1px solid #000;"> 
            ${totalAdjustment >= 0 ? "+" : ""}${totalAdjustment} HP 
          </div>
          <div style="font-size: 1em; text-align: center;">
            ${currentHP} &rarr; ${newHP}
          </div>
        </div>
      </div>`,
    sound: CONFIG.sounds.dice
  });
}
